-- Finance F6-1 (docs/finance-billing-f6.md §3): recurring invoice templates and their generation runs.
-- Generated by `prisma migrate diff`, then the constraints, guards, grants and RLS Prisma cannot
-- express were added by hand (section marked "hand-written"). Wrapped in one transaction
-- (docs/migration-readiness.md §7, STAB-M6).
--
-- Ordering: depends on 20261115000000_finance (finance_documents, FinanceDocumentKind), customers,
-- contacts and projects. It changes no existing table or row; it adds two tables and one audit
-- policy. It does NOT depend on F5 (20261122000000_finance_documents) or Reporting R1, and sorts after
-- both. Privileged SQL: prisma/privileged/002_finance_billing_due.sql (the scheduler's due-business
-- function) must be applied after this migration with `pnpm db:privileged`.
--
-- SQLSTATEs (class FN, finance): FN030 template identity or schedule fixed, FN031 invalid template
-- transition, FN032 run identity fixed or invalid run transition, FN033 a run's document is not a draft
-- invoice of the template's customer and currency.
BEGIN;
-- CreateTable
CREATE TABLE "finance_recurring_templates" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "customer_id" UUID NOT NULL,
    "contact_id" UUID,
    "project_id" UUID,
    "currency_code" CHAR(3) NOT NULL,
    "currency_scale" SMALLINT NOT NULL,
    "frequency" TEXT NOT NULL,
    "interval_count" SMALLINT NOT NULL DEFAULT 1,
    "start_date" DATE NOT NULL,
    "end_date" DATE,
    "time_zone" TEXT NOT NULL,
    "payment_terms_days" SMALLINT,
    "notes" TEXT,
    "lines" JSONB NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "next_period_index" INTEGER NOT NULL DEFAULT 0,
    "next_run_on" DATE,
    "paused_at" TIMESTAMPTZ,
    "cancelled_at" TIMESTAMPTZ,
    "cancelled_by_id" UUID,
    "ended_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_recurring_templates_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "finance_recurring_runs" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "template_id" UUID NOT NULL,
    "period_index" INTEGER NOT NULL,
    "period_date" DATE NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PENDING',
    "trigger" TEXT NOT NULL DEFAULT 'SCHEDULE',
    "requested_by_id" UUID,
    "attempts" SMALLINT NOT NULL DEFAULT 0,
    "max_attempts" SMALLINT NOT NULL DEFAULT 5,
    "run_after" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lease_id" UUID,
    "lease_expires_at" TIMESTAMPTZ,
    "document_id" UUID,
    "document_kind" "FinanceDocumentKind" NOT NULL DEFAULT 'INVOICE',
    "error_code" TEXT,
    "started_at" TIMESTAMPTZ,
    "finished_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_recurring_runs_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "finance_recurring_templates_business_id_status_next_run_on_idx" ON "finance_recurring_templates"("business_id", "status", "next_run_on");

-- CreateIndex
CREATE INDEX "finance_recurring_templates_business_id_customer_id_idx" ON "finance_recurring_templates"("business_id", "customer_id");

-- CreateIndex
CREATE INDEX "finance_recurring_templates_business_id_created_at_id_idx" ON "finance_recurring_templates"("business_id", "created_at" DESC, "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_recurring_templates_business_id_id_key" ON "finance_recurring_templates"("business_id", "id");

-- CreateIndex
CREATE INDEX "finance_recurring_runs_business_id_status_run_after_idx" ON "finance_recurring_runs"("business_id", "status", "run_after");

-- CreateIndex
CREATE INDEX "finance_recurring_runs_business_id_template_id_period_index_idx" ON "finance_recurring_runs"("business_id", "template_id", "period_index" DESC);

-- CreateIndex
CREATE UNIQUE INDEX "finance_recurring_runs_business_id_id_key" ON "finance_recurring_runs"("business_id", "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_recurring_runs_business_id_template_id_period_index_key" ON "finance_recurring_runs"("business_id", "template_id", "period_index");

-- CreateIndex
CREATE UNIQUE INDEX "finance_recurring_runs_business_id_document_id_key" ON "finance_recurring_runs"("business_id", "document_id");

-- AddForeignKey
ALTER TABLE "finance_recurring_templates" ADD CONSTRAINT "finance_recurring_templates_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_recurring_templates" ADD CONSTRAINT "finance_recurring_templates_customer_fkey" FOREIGN KEY ("business_id", "customer_id") REFERENCES "customers"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_recurring_templates" ADD CONSTRAINT "finance_recurring_templates_contact_fkey" FOREIGN KEY ("business_id", "contact_id") REFERENCES "contacts"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_recurring_templates" ADD CONSTRAINT "finance_recurring_templates_project_fkey" FOREIGN KEY ("business_id", "project_id") REFERENCES "projects"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_recurring_runs" ADD CONSTRAINT "finance_recurring_runs_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_recurring_runs" ADD CONSTRAINT "finance_recurring_runs_template_fkey" FOREIGN KEY ("business_id", "template_id") REFERENCES "finance_recurring_templates"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_recurring_runs" ADD CONSTRAINT "finance_recurring_runs_document_fkey" FOREIGN KEY ("business_id", "document_id", "document_kind") REFERENCES "finance_documents"("business_id", "id", "kind") ON DELETE NO ACTION ON UPDATE NO ACTION;



-- =============================================================================================
-- Hand-written: constraints, guards, grants and RLS.
-- =============================================================================================

-- ---- finance_recurring_templates ---------------------------------------------------------------
ALTER TABLE "finance_recurring_templates"
  ADD CONSTRAINT finance_recurring_templates_name_length CHECK (char_length("name") BETWEEN 1 AND 200),
  ADD CONSTRAINT finance_recurring_templates_currency_format CHECK ("currency_code" ~ '^[A-Z]{3}$' AND "currency_scale" BETWEEN 0 AND 4),
  ADD CONSTRAINT finance_recurring_templates_frequency_values CHECK ("frequency" IN ('WEEKLY', 'MONTHLY', 'QUARTERLY', 'ANNUAL')),
  ADD CONSTRAINT finance_recurring_templates_interval_range CHECK ("interval_count" BETWEEN 1 AND 12),
  ADD CONSTRAINT finance_recurring_templates_dates CHECK ("end_date" IS NULL OR "end_date" >= "start_date"),
  ADD CONSTRAINT finance_recurring_templates_zone_format CHECK ("time_zone" ~ '^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)*$' AND char_length("time_zone") <= 64),
  ADD CONSTRAINT finance_recurring_templates_terms_range CHECK ("payment_terms_days" IS NULL OR "payment_terms_days" BETWEEN 0 AND 365),
  ADD CONSTRAINT finance_recurring_templates_notes_length CHECK ("notes" IS NULL OR char_length("notes") <= 5000),
  ADD CONSTRAINT finance_recurring_templates_lines_shape CHECK (jsonb_typeof("lines") = 'array' AND jsonb_array_length("lines") BETWEEN 1 AND 200),
  ADD CONSTRAINT finance_recurring_templates_status_values CHECK ("status" IN ('ACTIVE', 'PAUSED', 'CANCELLED', 'ENDED')),
  ADD CONSTRAINT finance_recurring_templates_next_index CHECK ("next_period_index" >= 0),
  -- Status facts travel with their status, so a row can never claim to be both paused and cancelled.
  ADD CONSTRAINT finance_recurring_templates_paused_pair CHECK (("status" = 'PAUSED') = ("paused_at" IS NOT NULL)),
  ADD CONSTRAINT finance_recurring_templates_cancelled_pair CHECK (("status" = 'CANCELLED') = ("cancelled_at" IS NOT NULL)),
  ADD CONSTRAINT finance_recurring_templates_ended_pair CHECK (("status" = 'ENDED') = ("ended_at" IS NOT NULL)),
  -- Only a live schedule has a next run; it is never before the start or after the end.
  ADD CONSTRAINT finance_recurring_templates_next_run CHECK (
    (("status" IN ('ACTIVE', 'PAUSED')) = ("next_run_on" IS NOT NULL))
    AND ("next_run_on" IS NULL OR ("next_run_on" >= "start_date" AND ("end_date" IS NULL OR "next_run_on" <= "end_date")))),
  ADD CONSTRAINT finance_recurring_templates_version_positive CHECK ("version" >= 1);

CREATE FUNCTION finance_recurring_templates_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.created_at, NEW.created_by_id) IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.created_at, OLD.created_by_id) THEN
    RAISE EXCEPTION 'recurring template identity is fixed' USING ERRCODE = 'FN030';
  END IF;
  IF OLD.status IN ('CANCELLED', 'ENDED') THEN
    RAISE EXCEPTION 'a cancelled or ended recurring template is final' USING ERRCODE = 'FN031';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'ACTIVE' AND NEW.status IN ('PAUSED', 'CANCELLED', 'ENDED'))
    OR (OLD.status = 'PAUSED' AND NEW.status IN ('ACTIVE', 'CANCELLED'))) THEN
    RAISE EXCEPTION 'invalid recurring template transition' USING ERRCODE = 'FN031';
  END IF;
  -- Planning only moves forward: a period, once planned, is never planned again.
  IF NEW.next_period_index < OLD.next_period_index THEN
    RAISE EXCEPTION 'next period only moves forward' USING ERRCODE = 'FN030';
  END IF;
  -- Once a period exists, the schedule's identity is fixed, so the run history stays meaningful.
  IF (NEW.customer_id, NEW.currency_code, NEW.currency_scale, NEW.frequency, NEW.interval_count, NEW.start_date)
     IS DISTINCT FROM (OLD.customer_id, OLD.currency_code, OLD.currency_scale, OLD.frequency, OLD.interval_count, OLD.start_date)
     AND EXISTS (SELECT 1 FROM "finance_recurring_runs" r WHERE r."business_id" = OLD.business_id AND r."template_id" = OLD.id) THEN
    RAISE EXCEPTION 'schedule is fixed once a period exists' USING ERRCODE = 'FN030';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.paused_at := CASE WHEN NEW.status = 'PAUSED' THEN now() ELSE NULL END;
    IF NEW.status = 'CANCELLED' THEN NEW.cancelled_at := now(); END IF;
    IF NEW.status = 'ENDED' THEN NEW.ended_at := now(); END IF;
  ELSE
    NEW.paused_at := OLD.paused_at;
    NEW.cancelled_at := OLD.cancelled_at;
    NEW.ended_at := OLD.ended_at;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_recurring_templates_guard_update BEFORE UPDATE ON "finance_recurring_templates"
  FOR EACH ROW EXECUTE FUNCTION finance_recurring_templates_guard_update();

-- New templates start ACTIVE with no status facts; times are database time.
CREATE FUNCTION finance_recurring_templates_stamp_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NEW.status <> 'ACTIVE' OR NEW.next_period_index <> 0 THEN
    RAISE EXCEPTION 'a recurring template starts active at its first period' USING ERRCODE = 'FN031';
  END IF;
  NEW.paused_at := NULL; NEW.cancelled_at := NULL; NEW.cancelled_by_id := NULL; NEW.ended_at := NULL;
  NEW.created_at := now(); NEW.updated_at := now(); NEW.version := 1;
  RETURN NEW;
END $$;
CREATE TRIGGER finance_recurring_templates_stamp_insert BEFORE INSERT ON "finance_recurring_templates"
  FOR EACH ROW EXECUTE FUNCTION finance_recurring_templates_stamp_insert();

-- ---- finance_recurring_runs --------------------------------------------------------------------
ALTER TABLE "finance_recurring_runs"
  ADD CONSTRAINT finance_recurring_runs_status_values CHECK ("status" IN ('PENDING', 'RUNNING', 'GENERATED', 'FAILED', 'SKIPPED')),
  ADD CONSTRAINT finance_recurring_runs_trigger_values CHECK ("trigger" IN ('SCHEDULE', 'MANUAL')),
  ADD CONSTRAINT finance_recurring_runs_manual_requester CHECK (("trigger" = 'MANUAL') = ("requested_by_id" IS NOT NULL)),
  ADD CONSTRAINT finance_recurring_runs_period_index CHECK ("period_index" >= 0),
  ADD CONSTRAINT finance_recurring_runs_attempts_range CHECK ("attempts" >= 0 AND "max_attempts" BETWEEN 1 AND 50 AND "attempts" <= "max_attempts"),
  ADD CONSTRAINT finance_recurring_runs_document_kind CHECK ("document_kind" = 'INVOICE'),
  -- A running run always holds a lease; nothing else does.
  ADD CONSTRAINT finance_recurring_runs_lease_running CHECK ((("status" = 'RUNNING') = ("lease_id" IS NOT NULL)) AND (("lease_id" IS NULL) = ("lease_expires_at" IS NULL))),
  ADD CONSTRAINT finance_recurring_runs_finished_pair CHECK (("status" IN ('GENERATED', 'FAILED', 'SKIPPED')) = ("finished_at" IS NOT NULL)),
  -- Exactly the generated run points at its draft.
  ADD CONSTRAINT finance_recurring_runs_document_pair CHECK (("status" = 'GENERATED') = ("document_id" IS NOT NULL)),
  -- A stable code, never error text.
  ADD CONSTRAINT finance_recurring_runs_error_code_format CHECK ("error_code" IS NULL OR "error_code" ~ '^[a-z][a-z_]{1,48}$');

CREATE FUNCTION finance_recurring_runs_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  t record;
  d record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'PENDING' OR NEW.attempts <> 0 OR NEW.document_id IS NOT NULL THEN
      RAISE EXCEPTION 'a run starts pending' USING ERRCODE = 'FN032';
    END IF;
    NEW.created_at := now(); NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF (NEW.id, NEW.business_id, NEW.template_id, NEW.period_index, NEW.period_date, NEW.trigger, NEW.requested_by_id, NEW.document_kind, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.template_id, OLD.period_index, OLD.period_date, OLD.trigger, OLD.requested_by_id, OLD.document_kind, OLD.created_at) THEN
    RAISE EXCEPTION 'run identity is fixed' USING ERRCODE = 'FN032';
  END IF;
  IF OLD.status IN ('GENERATED', 'SKIPPED') THEN
    RAISE EXCEPTION 'generated and skipped runs are final' USING ERRCODE = 'FN032';
  END IF;
  IF NOT ((OLD.status = 'PENDING' AND NEW.status IN ('PENDING', 'RUNNING', 'SKIPPED'))
       OR (OLD.status = 'RUNNING' AND NEW.status IN ('RUNNING', 'PENDING', 'GENERATED', 'FAILED', 'SKIPPED'))
       OR (OLD.status = 'FAILED' AND NEW.status IN ('PENDING', 'SKIPPED'))) THEN
    RAISE EXCEPTION 'invalid run transition' USING ERRCODE = 'FN032';
  END IF;
  IF NEW.attempts < OLD.attempts OR NEW.max_attempts < OLD.max_attempts THEN
    RAISE EXCEPTION 'attempts only increase' USING ERRCODE = 'FN032';
  END IF;
  IF NEW.status = 'GENERATED' THEN
    -- The draft must be this template's: an invoice, still a draft, same customer and currency.
    SELECT "customer_id", "currency_code" INTO t FROM "finance_recurring_templates"
     WHERE "business_id" = NEW.business_id AND "id" = NEW.template_id;
    SELECT "customer_id", "currency_code", "status", "kind" INTO d FROM "finance_documents"
     WHERE "business_id" = NEW.business_id AND "id" = NEW.document_id;
    IF d IS NULL OR d.kind <> 'INVOICE' OR d.status <> 'DRAFT' OR d.customer_id <> t.customer_id OR d.currency_code <> t.currency_code THEN
      RAISE EXCEPTION 'a run generates a draft invoice of its template' USING ERRCODE = 'FN033';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_recurring_runs_guard BEFORE INSERT OR UPDATE ON "finance_recurring_runs"
  FOR EACH ROW EXECUTE FUNCTION finance_recurring_runs_guard();
REVOKE ALL ON FUNCTION finance_recurring_templates_guard_update(), finance_recurring_templates_stamp_insert(), finance_recurring_runs_guard() FROM PUBLIC;

-- ---- least privilege ---------------------------------------------------------------------------
-- No DELETE on either table: a template is cancelled and a run is skipped, never removed.
REVOKE ALL ON "finance_recurring_templates", "finance_recurring_runs" FROM bos_app;
GRANT SELECT, INSERT ON "finance_recurring_templates", "finance_recurring_runs" TO bos_app;
GRANT UPDATE ("name", "customer_id", "contact_id", "project_id", "currency_code", "currency_scale", "frequency", "interval_count", "start_date",
              "end_date", "time_zone", "payment_terms_days", "notes", "lines", "status", "next_period_index", "next_run_on", "paused_at",
              "cancelled_at", "cancelled_by_id", "ended_at", "version", "updated_by_id", "updated_at")
  ON "finance_recurring_templates" TO bos_app;
GRANT UPDATE ("status", "attempts", "max_attempts", "run_after", "lease_id", "lease_expires_at", "document_id", "error_code", "started_at",
              "finished_at", "updated_at")
  ON "finance_recurring_runs" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "finance_recurring_templates" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_recurring_templates" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_recurring_templates" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "finance_recurring_runs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "finance_recurring_runs" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "finance_recurring_runs" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

-- ---- audit: system events of the billing worker (D-F6-2) --------------------------------------
-- Like C2-A's audit_system_write: the scheduled worker has no acting user. Only finance.system.*
-- actions, only for this business, and only when the unit of work has no session user.
CREATE POLICY audit_finance_system_write ON "audit_events" FOR INSERT TO bos_app
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid
              AND "actor_user_id" IS NULL
              AND nullif(current_setting('app.user_id', true), '') IS NULL
              AND "action" LIKE 'finance.system.%');

COMMIT;
